INSERT @Apis VALUES
(1,N'toolbelt_core',N'VW_Events','SELECT',N'SELECT * FROM toolbelt_core.VW_Events;',N'DECLARE @EventExpected table(EventId bigint NULL,OccurredAtUtc datetime2(7) NULL,RecordedAtUtc datetime2(7) NULL,EventName varchar(128) COLLATE Latin1_General_100_BIN2 NULL,EventLevel varchar(16) COLLATE Latin1_General_100_BIN2 NULL,Category varchar(128) COLLATE Latin1_General_100_BIN2 NULL,Message nvarchar(4000) COLLATE Latin1_General_100_BIN2 NULL,DataJson nvarchar(max) COLLATE Latin1_General_100_BIN2 NULL,ExecutionId uniqueidentifier NULL,CorrelationId uniqueidentifier NULL,Actor nvarchar(256) COLLATE Latin1_General_100_BIN2 NULL,Tenant nvarchar(256) COLLATE Latin1_General_100_BIN2 NULL,SourceDatabaseName sysname COLLATE Latin1_General_100_BIN2 NULL,SourceSchemaName sysname COLLATE Latin1_General_100_BIN2 NULL,SourceObjectName sysname COLLATE Latin1_General_100_BIN2 NULL,CallerSessionId int NULL,CallerXactState smallint NULL,CallerTransactionCount int NULL,RemoteSessionId int NULL,ErrorNumber int NULL,ErrorSeverity int NULL,ErrorState int NULL,ErrorProcedure sysname COLLATE Latin1_General_100_BIN2 NULL,ErrorLine int NULL); INSERT @EventExpected VALUES (1,N''2020-01-01'',N''2024-01-01'',N''contoso.event-a'',N''INFO'',N''contoso'',N''Contoso fixture'',N''{"synthetic":true}'',N''11111111-1111-1111-1111-111111111111'',N''22222222-2222-2222-2222-222222222222'',N''Contoso'',N''Fabrikam'',N''Contoso'',N''toolbelt_core'',N''ContosoRoutine'',1,0,0,1,NULL,NULL,NULL,NULL,NULL),(2,N''2020-02-01'',N''2026-02-01'',N''contoso.event-b'',N''INFO'',N''contoso'',N''Contoso fixture'',N''{"synthetic":true}'',N''11111111-1111-1111-1111-111111111111'',N''22222222-2222-2222-2222-222222222222'',N''Contoso'',N''Fabrikam'',N''Contoso'',N''toolbelt_core'',N''ContosoRoutine'',1,0,0,1,NULL,NULL,NULL,NULL,NULL),(3,N''2026-03-01'',N''2024-03-01'',N''contoso.event-c'',N''INFO'',N''contoso'',N''Contoso fixture'',N''{"synthetic":true}'',N''11111111-1111-1111-1111-111111111111'',N''22222222-2222-2222-2222-222222222222'',N''Contoso'',N''Fabrikam'',N''Contoso'',N''toolbelt_core'',N''ContosoRoutine'',1,0,0,1,NULL,NULL,NULL,NULL,NULL),(4,N''2026-04-01'',N''2026-04-01'',N''contoso.event-d'',N''ERROR'',N''contoso'',N''Contoso fixture'',N''{"synthetic":true}'',N''11111111-1111-1111-1111-111111111111'',N''22222222-2222-2222-2222-222222222222'',N''Contoso'',N''Fabrikam'',N''Contoso'',N''toolbelt_core'',N''ContosoRoutine'',1,0,0,1,50001,16,1,N''ContosoRoutine'',1); IF (SELECT COUNT(*) FROM toolbelt_core.VW_Events)<>4 OR EXISTS(SELECT EventId,OccurredAtUtc,RecordedAtUtc,EventName COLLATE Latin1_General_100_BIN2,EventLevel COLLATE Latin1_General_100_BIN2,Category COLLATE Latin1_General_100_BIN2,Message COLLATE Latin1_General_100_BIN2,DataJson COLLATE Latin1_General_100_BIN2,ExecutionId,CorrelationId,Actor COLLATE Latin1_General_100_BIN2,Tenant COLLATE Latin1_General_100_BIN2,SourceDatabaseName COLLATE Latin1_General_100_BIN2,SourceSchemaName COLLATE Latin1_General_100_BIN2,SourceObjectName COLLATE Latin1_General_100_BIN2,CallerSessionId,CallerXactState,CallerTransactionCount,RemoteSessionId,ErrorNumber,ErrorSeverity,ErrorState,ErrorProcedure COLLATE Latin1_General_100_BIN2,ErrorLine FROM toolbelt_core.VW_Events EXCEPT SELECT EventId,OccurredAtUtc,RecordedAtUtc,EventName,EventLevel,Category,Message,DataJson,ExecutionId,CorrelationId,Actor,Tenant,SourceDatabaseName,SourceSchemaName,SourceObjectName,CallerSessionId,CallerXactState,CallerTransactionCount,RemoteSessionId,ErrorNumber,ErrorSeverity,ErrorState,ErrorProcedure,ErrorLine FROM @EventExpected) OR EXISTS(SELECT EventId,OccurredAtUtc,RecordedAtUtc,EventName,EventLevel,Category,Message,DataJson,ExecutionId,CorrelationId,Actor,Tenant,SourceDatabaseName,SourceSchemaName,SourceObjectName,CallerSessionId,CallerXactState,CallerTransactionCount,RemoteSessionId,ErrorNumber,ErrorSeverity,ErrorState,ErrorProcedure,ErrorLine FROM @EventExpected EXCEPT SELECT EventId,OccurredAtUtc,RecordedAtUtc,EventName COLLATE Latin1_General_100_BIN2,EventLevel COLLATE Latin1_General_100_BIN2,Category COLLATE Latin1_General_100_BIN2,Message COLLATE Latin1_General_100_BIN2,DataJson COLLATE Latin1_General_100_BIN2,ExecutionId,CorrelationId,Actor COLLATE Latin1_General_100_BIN2,Tenant COLLATE Latin1_General_100_BIN2,SourceDatabaseName COLLATE Latin1_General_100_BIN2,SourceSchemaName COLLATE Latin1_General_100_BIN2,SourceObjectName COLLATE Latin1_General_100_BIN2,CallerSessionId,CallerXactState,CallerTransactionCount,RemoteSessionId,ErrorNumber,ErrorSeverity,ErrorState,ErrorProcedure COLLATE Latin1_General_100_BIN2,ErrorLine FROM toolbelt_core.VW_Events) THROW 52097,N''EventLog fixed projection oracle.'',12;'),
(2,N'toolbelt_core',N'USP_DeleteEventsBefore','EXECUTE',N'EXEC toolbelt_core.USP_DeleteEventsBefore @Hilfe=1;',N'DECLARE @Before int=@@TRANCOUNT,@Rc int,@Deleted bigint,@Caught bit=0; IF @Before<>0 THROW 52097,N''EventLog initial transaction oracle.'',12; BEGIN TRANSACTION; BEGIN TRY EXEC @Rc=toolbelt_core.USP_DeleteEventsBefore @BeforeOccurredAtUtc=''2025-01-01T00:00:00'',@BatchSize=1,@MaxBatches=1,@DeletedRows=@Deleted OUTPUT; IF ISNULL(@Rc,-1)<>0 OR @Deleted<>1 OR @@TRANCOUNT<>@Before+1 OR XACT_STATE()<>1 THROW 52097,N''EventLog retention count oracle.'',12; EXEC @Rc=toolbelt_core.USP_DeleteEventsBefore @BeforeOccurredAtUtc=''2025-01-01T00:00:00'',@BatchSize=1,@MaxBatches=1,@DeletedRows=@Deleted OUTPUT; IF ISNULL(@Rc,-1)<>0 OR @Deleted<>1 OR @@TRANCOUNT<>@Before+1 OR XACT_STATE()<>1 THROW 52097,N''EventLog retention count oracle.'',12; EXEC @Rc=toolbelt_core.USP_DeleteEventsBefore @BeforeOccurredAtUtc=''2025-01-01T00:00:00'',@BatchSize=1,@MaxBatches=1,@DeletedRows=@Deleted OUTPUT; IF ISNULL(@Rc,-1)<>0 OR @Deleted<>0 OR @@TRANCOUNT<>@Before+1 OR XACT_STATE()<>1 THROW 52097,N''EventLog retention count oracle.'',12; BEGIN TRY EXEC toolbelt_core.USP_DeleteEventsBefore @BeforeOccurredAtUtc=''2025-01-01T00:00:00'',@BatchSize=0,@DeletedRows=@Deleted OUTPUT; END TRY BEGIN CATCH IF ERROR_NUMBER()<>51711 THROW; SET @Caught=1; END CATCH; IF @Caught<>1 OR @@TRANCOUNT<>@Before+1 OR XACT_STATE()<>1 THROW 52097,N''EventLog retention boundary oracle.'',12; ROLLBACK TRANSACTION; END TRY BEGIN CATCH IF @@TRANCOUNT>@Before ROLLBACK TRANSACTION; THROW; END CATCH; IF @@TRANCOUNT<>@Before OR XACT_STATE()<>0 THROW 52097,N''EventLog retention rollback oracle.'',12;'),
(3,N'toolbelt_core',N'USP_DeleteRecordedEventsBefore','EXECUTE',N'EXEC toolbelt_core.USP_DeleteRecordedEventsBefore @Hilfe=1;',N'DECLARE @Before int=@@TRANCOUNT,@Rc int,@Deleted bigint,@Caught bit=0; IF @Before<>0 THROW 52097,N''EventLog initial transaction oracle.'',12; BEGIN TRANSACTION; BEGIN TRY EXEC @Rc=toolbelt_core.USP_DeleteRecordedEventsBefore @BeforeRecordedAtUtc=''2025-01-01T00:00:00'',@BatchSize=1,@MaxBatches=1,@DeletedRows=@Deleted OUTPUT; IF ISNULL(@Rc,-1)<>0 OR @Deleted<>1 OR @@TRANCOUNT<>@Before+1 OR XACT_STATE()<>1 THROW 52097,N''EventLog retention count oracle.'',12; EXEC @Rc=toolbelt_core.USP_DeleteRecordedEventsBefore @BeforeRecordedAtUtc=''2025-01-01T00:00:00'',@BatchSize=1,@MaxBatches=1,@DeletedRows=@Deleted OUTPUT; IF ISNULL(@Rc,-1)<>0 OR @Deleted<>1 OR @@TRANCOUNT<>@Before+1 OR XACT_STATE()<>1 THROW 52097,N''EventLog retention count oracle.'',12; EXEC @Rc=toolbelt_core.USP_DeleteRecordedEventsBefore @BeforeRecordedAtUtc=''2025-01-01T00:00:00'',@BatchSize=1,@MaxBatches=1,@DeletedRows=@Deleted OUTPUT; IF ISNULL(@Rc,-1)<>0 OR @Deleted<>0 OR @@TRANCOUNT<>@Before+1 OR XACT_STATE()<>1 THROW 52097,N''EventLog retention count oracle.'',12; BEGIN TRY EXEC toolbelt_core.USP_DeleteRecordedEventsBefore @BeforeRecordedAtUtc=''2025-01-01T00:00:00'',@BatchSize=0,@DeletedRows=@Deleted OUTPUT; END TRY BEGIN CATCH IF ERROR_NUMBER()<>51711 THROW; SET @Caught=1; END CATCH; IF @Caught<>1 OR @@TRANCOUNT<>@Before+1 OR XACT_STATE()<>1 THROW 52097,N''EventLog retention boundary oracle.'',12; ROLLBACK TRANSACTION; END TRY BEGIN CATCH IF @@TRANCOUNT>@Before ROLLBACK TRANSACTION; THROW; END CATCH; IF @@TRANCOUNT<>@Before OR XACT_STATE()<>0 THROW 52097,N''EventLog retention rollback oracle.'',12;');
